<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pedido #{{ $order->id }} · {{ $venue->name }}</title><link rel="manifest" href="{{ route('public.manifest', ['subdomain' => $venue->subdomain]) }}"><meta name="theme-color" content="{{ $venue->primary_color ?? '#087f5b' }}"><style>:root{--brand:{{ $venue->primary_color ?? '#087f5b' }};--brand-dark:{{ $venue->secondary_color ?? '#102b3c' }};--dark:var(--brand-dark);--ink:#14221c;--muted:#66747d;--line:#dfe7e2}*{box-sizing:border-box}body{min-height:100vh;margin:0;display:flex;flex-direction:column;background:#f4f7f5;color:var(--ink);font:16px system-ui}.store-topbar{background:var(--brand);color:#fff;font-size:14px;font-weight:750}.store-topbar-inner{display:flex;align-items:center;justify-content:space-between;max-width:1400px;width:calc(100% - 32px);min-height:34px;margin:auto}.store-header{background:#fff;border-bottom:1px solid var(--line)}.store-header-main{max-width:1400px;width:calc(100% - 32px);min-height:100px;margin:auto;display:grid;grid-template-columns:minmax(190px,260px) minmax(300px,630px);justify-content:space-between;align-items:center;gap:28px}.store-brand{display:flex;align-items:center;gap:12px;color:var(--ink);text-decoration:none;font-size:25px;font-weight:900;line-height:.92}.store-logo{width:62px;height:62px;object-fit:cover;border-radius:50%;background:#e5eee9}.store-brand-text::after{content:'.';color:var(--brand)}.header-search{display:flex;align-items:center;gap:10px;padding:0 16px;border-radius:10px;background:#f4f5f4;color:var(--muted)}.header-search input{width:100%;border:0;outline:0;background:transparent;padding:15px 0;font:inherit}.header-search svg{width:20px}.category-rail{display:flex;gap:8px;max-width:1400px;width:calc(100% - 32px);margin:auto;padding:14px 0 3px;overflow:auto;border-bottom:1px solid var(--line)}.category-rail a{flex:none;border-bottom:3px solid transparent;padding:9px 13px;color:var(--muted);font-weight:750;text-decoration:none}.category-rail a.active{border-color:var(--brand);color:var(--ink);font-weight:900}.wrap{max-width:680px;margin:auto;padding:24px}.back{display:inline-flex;margin-bottom:18px;color:var(--brand);font-weight:800;text-decoration:none}.hero{border-radius:26px;background:linear-gradient(135deg,var(--dark),var(--brand));padding:28px;color:#fff}.hero h1{margin:10px 0}.status{display:inline-flex;border-radius:99px;background:#d9f7ea;color:#076349;padding:8px 13px;font-weight:800}.card{margin-top:18px;border:1px solid var(--line);border-radius:20px;background:#fff;padding:22px}.line{display:flex;justify-content:space-between;gap:12px;border-bottom:1px solid #edf1ee;padding:12px 0}.continue{display:block;margin-top:18px;border-radius:14px;background:var(--brand);color:#fff;padding:15px;text-align:center;text-decoration:none;font-weight:850}@media(max-width:720px){.store-topbar-inner,.store-header-main{width:calc(100% - 24px)}.store-topbar-inner{min-height:30px;font-size:12px}.store-header-main{display:block;padding:14px 0}.store-brand{font-size:21px}.store-logo{width:54px;height:54px}.header-search{margin-top:14px}.category-rail{width:100%;padding-left:12px;padding-right:12px}.wrap{padding:18px 12px}}</style></head><body>@include('public.partials.header', ['isMenu' => false])<main class="wrap"><a class="back" href="{{ route('public.menu',['subdomain'=>$venue->subdomain]) }}">← Voltar ao cardápio</a><header class="hero"><p style="margin:0;color:#c4f6df;font-weight:800">Acompanhamento do pedido</p><h1>Pedido #{{ $order->id }}</h1><span class="status">{{ trans('status.order.'.$order->status) }}</span><p style="margin-bottom:0">Esta página é atualizada automaticamente a cada 20 segundos.</p></header>@if($order->payment_mode === 'online')<section class="card" style="border-color:#b8c9ff"><h2 style="margin-top:0">Pagamento online</h2>@if($order->payment_status === 'approved')<p class="status">Pagamento aprovado</p><p>Seu pedido já pode ser confirmado pela equipe.</p>@elseif($order->payment_status === 'review_required')<p style="color:#9a3412;font-weight:800">Pagamento recebido após o cancelamento do pedido. Entre em contato com o estabelecimento para resolver o estorno.</p>@elseif($order->payment_status === 'expired')<p>O prazo de pagamento terminou e o pedido foi cancelado. Faça um novo pedido se ainda desejar.</p>@elseif($order->payment_status === 'refunded')<p>Este pagamento foi estornado. Fale com o estabelecimento se precisar de ajuda.</p>@else<p>O pedido só será enviado à equipe depois da confirmação do pagamento. Escolha PIX para pagar com QR Code no checkout seguro, ou pague com cartão.</p><form method="post" action="{{ route('public.order.pay',['subdomain'=>$venue->subdomain,'token'=>$order->public_token]) }}" class="mt-4">@csrf<button class="checkout" style="width:100%;border:0;cursor:pointer">{{ $order->payment_status === 'failed' ? 'Tentar pagamento novamente' : 'Pagar com Mercado Pago' }}</button></form>@endif</section>@endif<section class="card"><h2 style="margin-top:0">Seu pedido</h2>@foreach($order->items as $item)<div class="line"><span>{{ $item->quantity }}× {{ $item->name_snapshot }}</span><strong>R$ {{ number_format((float)$item->total,2,',','.') }}</strong></div>@endforeach<div class="line"><span>Entrega</span><span>R$ {{ number_format((float)$order->delivery_fee,2,',','.') }}</span></div><div class="line"><span>Desconto</span><span>- R$ {{ number_format((float)$order->discount,2,',','.') }}</span></div><div class="line" style="font-size:19px"><strong>Total</strong><strong>R$ {{ number_format((float)$order->total,2,',','.') }}</strong></div><a class="continue" href="{{ route('public.menu',['subdomain'=>$venue->subdomain]) }}">Continuar comprando</a></section></main>@include('public.partials.footer')<script>document.getElementById('productSearch')?.addEventListener('keydown',event=>{if(event.key!=='Enter')return;const term=event.currentTarget.value.trim();location.href=event.currentTarget.dataset.menuUrl+(term?'?busca='+encodeURIComponent(term):'');});setTimeout(()=>location.reload(),20000);if('serviceWorker'in navigator)navigator.serviceWorker.register('{{ route('public.service-worker',['subdomain'=>$venue->subdomain]) }}',{scope:'/'});</script></body></html>
